import { writeFile } from 'node:fs/promises'

import type { Ledger } from '../ledger/types.js'
import { toCsv } from './csv.js'

export type ExportFormat = 'csv'

export interface ExportOptions {
  format: ExportFormat
  out?: string
  stdout: boolean
  since?: string
}

/** Writes ledger entries to a file or stdout and returns the number of rows written. */
export async function runExport(ledger: Ledger, options: ExportOptions): Promise<number> {
  const rows = await ledger.entries({ since: options.since })
  const text = toCsv(rows)
  if (options.stdout) {
    process.stdout.write(text)
    return rows.length
  }
  await writeFile(options.out ?? 'ledger-export.csv', text)
  return rows.length
}

