import type { ExportFormat, ExportOptions } from './export.js'

const FORMATS: readonly ExportFormat[] = ['csv']

export function parseExportArgs(argv: string[]): ExportOptions {
  const options: ExportOptions = { format: 'csv', stdout: false }
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i]!
    if (arg === '--stdout') options.stdout = true
    else if (arg === '--out') options.out = argv[++i]
    else if (arg === '--since') options.since = argv[++i]
    else if (arg === '--format') {
      const value = argv[++i] as ExportFormat
      if (!FORMATS.includes(value)) throw new Error(`unknown format: ${value}`)
      options.format = value
    } else throw new Error(`unknown argument: ${arg}`)
  }
  return options
}

