import { describe, expect, test } from 'bun:test'

import { runExport } from '../../src/cli/export.js'

describe('runExport', () => {
  test('writes one csv row per entry and returns the count', async () => {
    const chunks: string[] = []
    const original = process.stdout.write.bind(process.stdout)
    process.stdout.write = ((chunk: string) => (chunks.push(chunk), true)) as typeof process.stdout.write
    try {
      const ledger = { entries: async () => [{ id: 'e1', amountMinor: 1200, currency: 'EUR', postedAt: '2026-11-01' }] }
      expect(await runExport(ledger, { format: 'csv', stdout: true })).toBe(1)
    } finally {
      process.stdout.write = original
    }
    expect(chunks.join('')).toContain('e1,1200,EUR,2026-11-01')
  })
})
